19	    private static SearchResult search(int[] arr, int target) {
20	        SearchRange range = SearchRange.forArray(arr);
21	
22	        while (range.isValid()) {
23	            int middleIndex = range.middleIndex();
24	            int middleValue = arr[middleIndex];
25	
26	            if (middleValue == target) {
27	                return SearchResult.foundAt(middleIndex);
28	            }
29	
30	            if (middleValue < target) {
31	                range = range.discardLowerHalf(middleIndex);
32	            } else {
33	                range = range.discardUpperHalf(middleIndex);
34	            }
35	        }
36	
37	        return SearchResult.notFound();
38	    }
