40	    private record SearchRange(int low, int high) {
41	        private static SearchRange forArray(int[] arr) {
42	            return new SearchRange(0, arr.length - 1);
43	        }
44	
45	        private boolean isValid() {
46	            return low <= high;
47	        }
48	
